// Mirrors backend/app/schemas (contracts.py, claims.py).
// TODO(Kissa): replace with types generated by `npx openapi-typescript`.

export type Role = 'citizen' | 'helper' | 'officer' | 'admin' | 'auditor'
export type Route = 'AUTO_APPROVE' | 'ASK_PROOF' | 'UNSURE'
export type DocumentKind = 'death_certificate' | 'claimant_cnic' | 'frc' | 'nikah_nama'

export type SessionUser = { id: string; name: string; role: Role; tenant_id: string; person_id: string | null }
export type LoginResult = { access_token: string; refresh_token: string; user: SessionUser }

export type Me = {
  id: string
  role: Role
  name: string | null
  person: { id: string; cnic: string; name: string } | null
}

// cnic is null when the family has not shared it with this helper (no active consent).
export type Family = { id: string; cnic: string | null; name: string; consent_active?: boolean }

export type DecisionSummary = {
  id: string
  route: Route
  reason_codes: string[]
  confidence: number
  rule_version: number
  model_id: string | null
  created_at: string
}

export type CaseView = {
  id: string
  reference: string
  status: string
  priority: number
  confidence: number | null
  claimant_person_id: string
  assigned_officer_id: string | null
  deceased_cnic: string | null
  created_at: string
  latest_decision: DecisionSummary | null
}

export type Explanation = { reason_code: string; text_ur: string; text_en: string; audio_key: string; icon: string }

export type CitizenExplanation = {
  case_reference: string
  status: string
  route: Route | null
  explanations: Explanation[]
  missing_items: string[]
  entitlement_end: string | null
}

export type ClaimIn = {
  claimant_cnic: string
  claimant_name: string
  relation_claimed: 'widow' | 'son' | 'daughter'
  deceased_cnic: string | null
  deceased_name: string
  payout_iban: string
  documents: DocumentKind[]
}

export type AuditRow = {
  seq: number
  ts: string
  actor_type: string
  role: string | null
  action: string
  resource: string | null
  details: Record<string, unknown>
}

export type ConsentField = 'cnic' | 'family_record' | 'death_certificate' | 'payout_account' | 'case_details'

export type Consent = {
  id: string
  grantee_type: 'helper' | 'department'
  grantee_id: string
  grantee_name: string
  fields: ConsentField[]
  status: 'active' | 'withdrawn'
  created_at: string
  withdrawn_at: string | null
}

export type ConsentList = { fields: ConsentField[]; consents: Consent[] }

export type AccessLogRow = {
  seq: number
  ts: string
  action: string
  who: string
  role: string | null
  field: string | null
  basis: string | null
}

export type CorrectionField = 'name' | 'date_of_birth' | 'payout_account' | 'family_record'

export type RuleDef = { id: string; title?: string; basis?: string; reason?: string }

export type RuleVersionRow = {
  id: string
  ruleset: string
  version: number
  label: string
  status: 'live' | 'draft' | 'retired'
  effective_from: string | null
  thresholds: Record<string, number>
  rules: RuleDef[]
}

export type TwinOutcome = { route: string; reasons: string[]; entitlement_end: string | null }

export type TwinCase = { case: string; status: string; before: TwinOutcome; after: TwinOutcome; changed: string[] }

export type Simulation = { draft_version: number; checked: number; changed: number; cases: TwinCase[] }
